UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.prompt = 'Read the passage. What does the passage indicate about coral reefs and marine species?' WHERE e.exam_code = 'TP-PRACTICE-2026-MINI' AND q.order_no = 7;
UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.prompt = 'The word "expel" in the passage is closest in meaning to:', q.body_text = 'Coral reefs cover less than one percent of the ocean floor yet support roughly a quarter of all marine species. This disparity is explained by the structure reefs provide: a three-dimensional habitat with countless niches. When water temperatures rise beyond a narrow tolerance range, corals expel the symbiotic algae that supply most of their energy, a process known as bleaching. Bleached corals are not dead, and they can recover if conditions normalize quickly enough. Prolonged warm periods, however, shift the balance from recovery to mortality, and repeated events simplify the reef structure, reducing the number of available niches and the biodiversity they supported.' WHERE e.exam_code = 'TP-PRACTICE-2026-MINI' AND q.order_no = 8;
UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.choices_json = '["It was founded in 1998.","On the second floor, next to the lab.","The printer is out of paper.","Yes, it sounds interesting."]', q.answer_key = 'D', q.explanation = 'An invitation is best answered with acceptance or decline; option D responds directly.' WHERE e.exam_code = 'TP-PRACTICE-2026-MINI' AND q.order_no = 9;
UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.prompt = 'Listen to the conversation. What does the man say about shortening the reservation?', q.choices_json = '["The reservation cannot be changed at all.","He will shorten it for her automatically.","She has to pay for two hours no matter what.","It can be shortened only on the day the room is used."]', q.answer_key = 'D' WHERE e.exam_code = 'TP-PRACTICE-2026-MINI' AND q.order_no = 12;
UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.prompt = 'Listen to the conversation. Where can the student look at the scanned copy?' WHERE e.exam_code = 'TP-PRACTICE-2026-MINI' AND q.order_no = 13;
UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.prompt = 'Listen to the announcement. What has been cancelled?' WHERE e.exam_code = 'TP-PRACTICE-2026-MINI' AND q.order_no = 14;
