UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.choices_json = '["How much pavement costs in a mid-sized city","How to design a tall building in a warm climate","Why trees should be removed from busy intersections","Why cities stay hot at night and how two remedies compare"]', q.body_text = 'Many cities stay several degrees warmer than the surrounding countryside after sunset. The effect, called the urban heat island, appears because pavement and dark roofs absorb sunlight during the day and release the heat slowly at night, while vegetation cools the air by evaporating water through its leaves. Tall buildings add to the problem by trapping warmed air at street level and slowing the wind that would carry it away. Planners now test two inexpensive remedies: coating roofs and roads with reflective paint, and restoring tree canopy above busy intersections. Measurements in several mid-sized cities suggest that reflective coatings cool a street by about one degree, whereas mature trees cool the air beneath them by three degrees or more while also shading the surfaces that store heat.', q.answer_key = 'D' WHERE e.exam_code = 'TP-PRACTICE-2026-SET02' AND q.order_no = 36;
UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.body_text = 'Many cities stay several degrees warmer than the surrounding countryside after sunset. The effect, called the urban heat island, appears because pavement and dark roofs absorb sunlight during the day and release the heat slowly at night, while vegetation cools the air by evaporating water through its leaves. Tall buildings add to the problem by trapping warmed air at street level and slowing the wind that would carry it away. Planners now test two inexpensive remedies: coating roofs and roads with reflective paint, and restoring tree canopy above busy intersections. Measurements in several mid-sized cities suggest that reflective coatings cool a street by about one degree, whereas mature trees cool the air beneath them by three degrees or more while also shading the surfaces that store heat.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET02' AND q.order_no = 37;
