UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.choices_json = '["Cold temperatures freeze the carbon","Its plants grow extremely fast","It is covered by forest","Partial decomposition leaves plant material buried instead of rotted"]', q.body_text = 'Environmental science lecture. Peat bogs cover only a few percent of the land surface, yet they hold more carbon than all the world''s forests. The reason is slow decay. In a waterlogged, acidic, oxygen-poor bog, dead plant material does not rot completely, so year after year a partially preserved layer accumulates and the carbon its plants drew from the air stays locked underground. Drain a bog for farming and air enters the peat; the stored carbon then decomposes and the site turns from a sink into a source, releasing centuries of accumulation in a few decades. Rewetting can halt that loss, but new peat forms at roughly a millimetre per year, which is why conservationists treat an intact bog as something close to irreplaceable.', q.answer_key = 'D' WHERE e.exam_code = 'TP-PRACTICE-2026-SET02' AND q.order_no = 94;
