UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.body_text = 'Long before any European government issued paper money, merchants in the Chinese region of Sichuan were already using it. Under the Song dynasty, which began in 960, currency there was heavy iron coin, so awkward to carry that a large purchase needed a cartload of metal. Records describe privately issued notes, each promising the bearer a set number of coins at a named shop, circulating instead of the coins themselves. The court first treated these notes as a convenient local habit, then recognised their value as a source of revenue and, in the early eleventh century, opened state workshops that printed official notes on mulberry bark paper with coloured ink and registered serial numbers. Forgery was punished severely, yet repeated overissue to pay for military spending undermined confidence, and the dynasty revised its note series so often that historians now trace monetary policy through the changing denominations.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET03' AND q.order_no = 39;
UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.choices_json = '["strengthened","paid for","recorded","weakened"]', q.body_text = 'Long before any European government issued paper money, merchants in the Chinese region of Sichuan were already using it. Under the Song dynasty, which began in 960, currency there was heavy iron coin, so awkward to carry that a large purchase needed a cartload of metal. Records describe privately issued notes, each promising the bearer a set number of coins at a named shop, circulating instead of the coins themselves. The court first treated these notes as a convenient local habit, then recognised their value as a source of revenue and, in the early eleventh century, opened state workshops that printed official notes on mulberry bark paper with coloured ink and registered serial numbers. Forgery was punished severely, yet repeated overissue to pay for military spending undermined confidence, and the dynasty revised its note series so often that historians now trace monetary policy through the changing denominations.', q.answer_key = 'D' WHERE e.exam_code = 'TP-PRACTICE-2026-SET03' AND q.order_no = 40;
UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.choices_json = '["It exported its notes to Europe","It forbade merchants from using any written promise","It stopped using coins after 960","It took over note production partly because the notes raised money for the state"]', q.body_text = 'Long before any European government issued paper money, merchants in the Chinese region of Sichuan were already using it. Under the Song dynasty, which began in 960, currency there was heavy iron coin, so awkward to carry that a large purchase needed a cartload of metal. Records describe privately issued notes, each promising the bearer a set number of coins at a named shop, circulating instead of the coins themselves. The court first treated these notes as a convenient local habit, then recognised their value as a source of revenue and, in the early eleventh century, opened state workshops that printed official notes on mulberry bark paper with coloured ink and registered serial numbers. Forgery was punished severely, yet repeated overissue to pay for military spending undermined confidence, and the dynasty revised its note series so often that historians now trace monetary policy through the changing denominations.', q.answer_key = 'D' WHERE e.exam_code = 'TP-PRACTICE-2026-SET03' AND q.order_no = 41;
UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.body_text = 'Oats were the last major cereal to be domesticated, and they arrived in the field uninvited. When farmers in the Fertile Crescent grew wheat and barley, wild oat seeds fell among the grain and were carried home, threshed, and sown again with the crop. The plant was therefore a weed in wheat before it was a crop in its own right. Its adoption made sense in cooler, wetter northern Europe, where wheat yields poorly while oats put up with damp soil and a short season. Because oats keep their grain inside a tough husk, they store well through a long winter, an advantage for communities without dry granaries. The archaeological record points the same way: once oats were planted deliberately, storage improved as well. The larger shift may have come after harvesting, since hulled oats soften only after long heating and stirring, a method that suits households with fuel to spare.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET03' AND q.order_no = 45;
