UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.body_text = 'A common mistake is to treat signed languages as finger spelling or as loose gestures that pantomime speech. Linguists who study them report something very different. American Sign Language, Japanese Sign Language, and dozens of others have the equipment of any spoken tongue: a stock of basic units, rules for combining them, and ways to mark tense, question, and negation. A signer uses the space in front of the body to place a person or a field and then points back to it, an economy that spoken languages achieve with pronouns. Word order bends to carry emphasis, and small changes in hand shape flip a meaning. That signed grammar is full and rule-governed matters outside the lecture hall; it shapes how children born deaf acquire language and how schools should teach them.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET05' AND q.order_no = 45;
