UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.prompt = 'Listen to the talk. What is the talk mainly about?', q.choices_json = '["How writing grew out of the need to record rations","The origin of poetry on clay tablets","The daily diet of temple workers","The trade routes for barley"]', q.body_text = 'Professor: Today we look at why the first writing was almost boring. The oldest clay tablets from southern Mesopotamia are not poems or prayers; they are tallies of grain, beer, and sheep handed out as rations. A worker received a fixed measure of barley each day, and the temple had to record who took it, or the storehouse would be emptied without a trace. So the earliest signs are numbers, a picture of a stalk, and a mark naming the person. Only later did the wedge-shaped strokes become flexible enough to say more than a receipt. The lesson is that a technology we now link with literature and law grew out of a plain accounting need: keeping track of what was owed to whom. That is why, when you read a ration list, you are seeing writing at its first everyday work, pressed into wet clay.', q.answer_key = 'A', q.explanation = 'The talk explains that the earliest tablets recorded grain and beer rations, so writing grew out of an accounting need.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET05' AND q.order_no = 90;
UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.prompt = 'Listen to the talk. Why does the professor call the first writing "almost boring"?', q.body_text = 'Professor: Today we look at why the first writing was almost boring. The oldest clay tablets from southern Mesopotamia are not poems or prayers; they are tallies of grain, beer, and sheep handed out as rations. A worker received a fixed measure of barley each day, and the temple had to record who took it, or the storehouse would be emptied without a trace. So the earliest signs are numbers, a picture of a stalk, and a mark naming the person. Only later did the wedge-shaped strokes become flexible enough to say more than a receipt. The lesson is that a technology we now link with literature and law grew out of a plain accounting need: keeping track of what was owed to whom. That is why, when you read a ration list, you are seeing writing at its first everyday work, pressed into wet clay.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET05' AND q.order_no = 91;
UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.prompt = 'Listen to the talk. What do the oldest clay tablets from southern Mesopotamia contain?', q.body_text = 'Professor: Today we look at why the first writing was almost boring. The oldest clay tablets from southern Mesopotamia are not poems or prayers; they are tallies of grain, beer, and sheep handed out as rations. A worker received a fixed measure of barley each day, and the temple had to record who took it, or the storehouse would be emptied without a trace. So the earliest signs are numbers, a picture of a stalk, and a mark naming the person. Only later did the wedge-shaped strokes become flexible enough to say more than a receipt. The lesson is that a technology we now link with literature and law grew out of a plain accounting need: keeping track of what was owed to whom. That is why, when you read a ration list, you are seeing writing at its first everyday work, pressed into wet clay.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET05' AND q.order_no = 92;
UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.prompt = 'Listen to the talk. What happened to the early writing signs over time?', q.choices_json = '["They were lost","They became the alphabet overnight","They later became able to say more than a receipt","They stopped recording barley"]', q.body_text = 'Professor: Today we look at why the first writing was almost boring. The oldest clay tablets from southern Mesopotamia are not poems or prayers; they are tallies of grain, beer, and sheep handed out as rations. A worker received a fixed measure of barley each day, and the temple had to record who took it, or the storehouse would be emptied without a trace. So the earliest signs are numbers, a picture of a stalk, and a mark naming the person. Only later did the wedge-shaped strokes become flexible enough to say more than a receipt. The lesson is that a technology we now link with literature and law grew out of a plain accounting need: keeping track of what was owed to whom. That is why, when you read a ration list, you are seeing writing at its first everyday work, pressed into wet clay.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET05' AND q.order_no = 93;
