UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.body_text = 'Most land plants grow alongside fungi whose thread-like hyphae spread through the soil and connect to roots, forming what researchers call a mycorrhizal network. The exchange is mutual: the fungus, which cannot photosynthesise, receives sugars from the plant, while its fine threads gather water and minerals that the plant''s own roots could not reach alone. Through a single network several plants can be linked at once, and experiments with tagged carbon have shown that sugars and chemical warning signals pass between them, sometimes from older sunlit trees toward younger ones in deep shade. Whether this amounts to genuine cooperation or merely to shared pathways is contested; the fungi serve their own growth, and a network can equally move resources toward the plants that feed them most. What is not in doubt is that forest soils are threaded with living connections that bind individual plants into one functioning system.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET06' AND q.order_no = 42;
