UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.prompt = 'According to the passage, why was the high wheeler considered dangerous?', q.body_text = 'Before the 1880s the common bicycle was the high wheeler, whose huge front wheel gave speed but placed the rider far above the ground, so a stone or a rut could throw the rider head first over the handlebars in a feared accident called a header. The machine that replaced it was nicknamed the safety bicycle because its two equal wheels, diamond frame, and chain drive kept the rider seated low between the wheels, and rubber pneumatic tyres after 1888 smoothed the ride further. Crucially, pedalling turned the rear wheel through a chain rather than driving the front directly, so the frame could be built strong and light. Cheaper production after 1890 brought the price within reach of ordinary workers, and cycling clubs spread rapidly. Historians credit the safety bicycle with more personal independence for women and city workers than almost any earlier machine, since for the first time affordable travel did not depend on a horse or a paid fare.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET06' AND q.order_no = 45;
