UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.body_text = 'For most of history people could name the mountains on land but not the shape of the ocean floor beneath their ships. The instrument that changed this is echo sounding, or sonar: a vessel sends a pulse of sound downward, times how long the echo takes to return, and converts that interval into depth using the known speed of sound in water. Early measurements came one at a time along a ship''s track, mapping a single narrow line. Modern surveys instead send out a fan of many beams that together image a wide swath of seabed, and satellites estimate depth from tiny bumps in the sea surface that betray the mass below. Repeated sounding has revealed a global system of mid-ocean ridges, deep trenches, and flat sediment plains, evidence that helped geologists confirm that the seafloor spreads. Even now, high-resolution maps cover only a fraction of the ocean, so most of the planet''s largest landscape remains surveyed only coarsely.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET06' AND q.order_no = 48;
