UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.prompt = 'Why does the passage mention apprentices and guild courts?', q.body_text = 'Craft guilds in medieval towns are often remembered for guarding their recipes, and the habit had real economic logic. A guild''s income depended on a craft being harder to learn than it looked, so a glassmaker who revealed the exact mix of ashes and sand risked undercutting every fellow member in town. Rules on disclosure were therefore collective: an apprentice swore not to copy a formula into a book a stranger could buy, and a full member who trained an outsider''s son could be fined by the guild court. Yet secrecy cut both ways. Keeping a technique rare helped the few families who held it, but it also slowed the diffusion of useful methods across towns, so a clever dye or a stronger kiln might vanish when its last practitioner died. Historians now argue that the guild system traded broad technological spread for narrow price protection, and that the shift came only when patents promised inventors a timed reward and open publication in place of permanent silence.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET07' AND q.order_no = 39;
UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.body_text = 'Craft guilds in medieval towns are often remembered for guarding their recipes, and the habit had real economic logic. A guild''s income depended on a craft being harder to learn than it looked, so a glassmaker who revealed the exact mix of ashes and sand risked undercutting every fellow member in town. Rules on disclosure were therefore collective: an apprentice swore not to copy a formula into a book a stranger could buy, and a full member who trained an outsider''s son could be fined by the guild court. Yet secrecy cut both ways. Keeping a technique rare helped the few families who held it, but it also slowed the diffusion of useful methods across towns, so a clever dye or a stronger kiln might vanish when its last practitioner died. Historians now argue that the guild system traded broad technological spread for narrow price protection, and that the shift came only when patents promised inventors a timed reward and open publication in place of permanent silence.', q.explanation = 'Revealing a recipe erodes the market advantage of fellow guild members, so "undercutting" means damaging the position of.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET07' AND q.order_no = 40;
