UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.body_text = 'Coastal engineering once meant pouring concrete, but a growing number of planners are looking instead at mangroves, the salt-tolerant trees that fringe tropical shores. Mangroves defend a coastline in two ways. Their dense, submerged roots spread a rolling wave into many small ripples, and the friction between root and water drains a storm surge of speed and height, so the water that reaches a village arrives as a shallow sheet rather than a hammering wall. The same roots also act as a trap for sediment, slowing the current until suspended mud falls out and the shoreline builds seaward on its own, a self-repair a rigid seawall can never manage. That said, a mangrove is not a universal solution. It needs a gently sloping shore and a steady supply of fresh water from upstream, so damming a river can starve the trees and let erosion undo years of protection in a single storm season.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET07' AND q.order_no = 42;
UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.body_text = 'Coastal engineering once meant pouring concrete, but a growing number of planners are looking instead at mangroves, the salt-tolerant trees that fringe tropical shores. Mangroves defend a coastline in two ways. Their dense, submerged roots spread a rolling wave into many small ripples, and the friction between root and water drains a storm surge of speed and height, so the water that reaches a village arrives as a shallow sheet rather than a hammering wall. The same roots also act as a trap for sediment, slowing the current until suspended mud falls out and the shoreline builds seaward on its own, a self-repair a rigid seawall can never manage. That said, a mangrove is not a universal solution. It needs a gently sloping shore and a steady supply of fresh water from upstream, so damming a river can starve the trees and let erosion undo years of protection in a single storm season.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET07' AND q.order_no = 43;
UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.choices_json = '["They can add new land after every major storm.","They cannot rebuild the shoreline the way mangrove roots do.","They trap more sediment than mangrove roots do.","They need far more fresh water than a mangrove."]', q.body_text = 'Coastal engineering once meant pouring concrete, but a growing number of planners are looking instead at mangroves, the salt-tolerant trees that fringe tropical shores. Mangroves defend a coastline in two ways. Their dense, submerged roots spread a rolling wave into many small ripples, and the friction between root and water drains a storm surge of speed and height, so the water that reaches a village arrives as a shallow sheet rather than a hammering wall. The same roots also act as a trap for sediment, slowing the current until suspended mud falls out and the shoreline builds seaward on its own, a self-repair a rigid seawall can never manage. That said, a mangrove is not a universal solution. It needs a gently sloping shore and a steady supply of fresh water from upstream, so damming a river can starve the trees and let erosion undo years of protection in a single storm season.', q.explanation = 'The passage calls mangrove shoreline-building a self-repair a rigid seawall can never manage, so a wall cannot rebuild the coast.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET07' AND q.order_no = 44;
UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.choices_json = '["To compare two scholars who worked to decipher the stone and to stress the value of the Greek text.","To prove that hieroglyphs were never really understood.","To describe the daily life of priests who wrote the decree.","To explain why Napoleon''s army was defeated in Egypt."]', q.body_text = 'When Napoleon''s soldiers found a black stone near the town of Rosetta in 1799, they did not know they held a key. The stone carries one decree in three scripts: Egyptian hieroglyphs at the top, a cursive Demotic section in the middle, and ancient Greek at the bottom. Because scholars could already read Greek, the parallel text let them match known words to unknown signs, and the same passage repeated three times meant a guess could be tested against two independent versions. Two men raced to crack the code. Thomas Young treated the hieroglyphs as a partly symbolic code and decoded a royal name, but he doubted that ordinary Egyptian words were written by sound. Jean-Francois Champollion, fluent in Coptic, argued the script recorded sounds and, in 1822, announced a working alphabet. Their rivalry shows how a single object can move a whole field forward, though the harder lesson is one of luck: without the Greek text, the other two scripts might have stayed unread for centuries.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET07' AND q.order_no = 45;
