UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.choices_json = '["He believed the whole script was purely phonetic.","He could read every one of the stone''s three scripts.","He treated the signs as mainly ideas rather than sounds.","He refused to use the Greek text at all."]', q.body_text = 'When Napoleon''s soldiers found a black stone near the town of Rosetta in 1799, they did not know they held a key. The stone carries one decree in three scripts: Egyptian hieroglyphs at the top, a cursive Demotic section in the middle, and ancient Greek at the bottom. Because scholars could already read Greek, the parallel text let them match known words to unknown signs, and the same passage repeated three times meant a guess could be tested against two independent versions. Two men raced to crack the code. Thomas Young treated the hieroglyphs as a partly symbolic code and decoded a royal name, but he doubted that ordinary Egyptian words were written by sound. Jean-Francois Champollion, fluent in Coptic, argued the script recorded sounds and, in 1822, announced a working alphabet. Their rivalry shows how a single object can move a whole field forward, though the harder lesson is one of luck: without the Greek text, the other two scripts might have stayed unread for centuries.', q.explanation = 'The passage says Young decoded a name but doubted that ordinary words were written by sound, so he saw the script as mainly symbolic.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET07' AND q.order_no = 47;
UPDATE tp_questions q JOIN tp_exams e ON e.exam_id = q.exam_id SET q.body_text = 'A shift nurse finishing at dawn feels the exhaustion the body was built to expect, but the reason is simpler than anyone admits. Nearly every cell runs on a circadian clock, a roughly twenty-four-hour cycle tuned to light and dark, which times hormone release, body temperature, and alertness. Daylight resets that clock each morning, yet a worker who sleeps through it receives the signal late or not at all. The consequences show up as drift rather than collapse: digestion, mood, and reaction speed slip out of step, and long-term studies have linked years of night work to higher rates of metabolic trouble. Trying to fix the clock with a nap often backfires, because the sleep debt lingers. Chronobiologists therefore argue that the practical answer is not a stronger will but a smarter schedule, with forward-rotating shifts, in which each new start time falls later than the last, and timed bright light, so the body''s clock can follow the calendar instead of resisting it.' WHERE e.exam_code = 'TP-PRACTICE-2026-SET07' AND q.order_no = 48;
