-- ===== 정답 위치를 바꾼 94문항: 이미 저장된 응시 답 글자도 같은 맞바꿈으로 옮긴다 =====
-- 객관식 답은 tp_attempt_answers.answer_text 에 글자(A~D)로 저장된다. 옮기지 않으면 지난 결과의 "내 답"이 다른 문구를 가리키고,
-- 풀던 중인 응시(IN_PROGRESS)의 답이 새 정답 키로 채점된다. is_correct 는 건드리지 않고, updated_at 도 그대로 둔다.
-- 문항은 exam_code + order_no 로 찾으므로 위 문항 UPDATE 와의 순서는 결과에 영향이 없다.
UPDATE tp_attempt_answers a JOIN tp_questions q ON q.question_id = a.question_id JOIN tp_exams e ON e.exam_id = q.exam_id SET a.answer_text = CASE UPPER(TRIM(a.answer_text)) WHEN 'A' THEN 'D' WHEN 'D' THEN 'A' ELSE a.answer_text END, a.updated_at = a.updated_at WHERE e.exam_code = 'TP-PRACTICE-2026-MINI' AND q.order_no = 1 AND UPPER(TRIM(a.answer_text)) IN ('A', 'D');
UPDATE tp_attempt_answers a JOIN tp_questions q ON q.question_id = a.question_id JOIN tp_exams e ON e.exam_id = q.exam_id SET a.answer_text = CASE UPPER(TRIM(a.answer_text)) WHEN 'A' THEN 'D' WHEN 'D' THEN 'A' ELSE a.answer_text END, a.updated_at = a.updated_at WHERE e.exam_code = 'TP-PRACTICE-2026-MINI' AND q.order_no = 4 AND UPPER(TRIM(a.answer_text)) IN ('A', 'D');
